import { useState, useEffect } from 'react';

function VehicleList({ user, onRent, onViewDetail }) {
  const [vehicles, setVehicles] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchVehicles = async () => {
      setLoading(true);
      const res = await fetch('http://localhost:3002/api/vehicles');
      const data = await res.json();
      setVehicles(data);
      setLoading(false);
    };
    fetchVehicles();
  }, []);

  if (loading) return <div className="loading">Loading vehicles...</div>;

  const available = vehicles.filter((v) => v.available);

  return (
    <div className="vehicle-list">
      <h2>Available Vehicles</h2>
      {available.length === 0 ? (
        <p className="no-vehicles">No vehicles available at the moment.</p>
      ) : (
        <div className="vehicle-grid">
          {available.map((vehicle) => (
            <div
              key={vehicle.id}
              className="vehicle-card"
              onClick={() => onViewDetail(vehicle)}
              style={{ cursor: 'pointer' }}
            >
              <div className="vehicle-img-wrap">
                {vehicle.image ? (
                  <img
                    src={vehicle.image.startsWith('http') ? vehicle.image : `/images/${vehicle.image}`}
                    alt={`${vehicle.brand} ${vehicle.model}`}
                    className="vehicle-img"
                    onError={(e) => {
                      e.target.style.display = 'none';
                      e.target.nextSibling.style.display = 'flex';
                    }}
                  />
                ) : null}
                <div
                  className="vehicle-img-fallback"
                  style={{ display: vehicle.image ? 'none' : 'flex' }}
                >
                  🚗
                </div>
              </div>
              <div className="vehicle-card-body">
                <h3>{vehicle.brand} {vehicle.model}</h3>
                <div className="vehicle-details">
                  <span className="badge">{vehicle.segment}</span>
                  <p>📍 {vehicle.campus}</p>
                  <p className="price">₺{vehicle.pricePerDay}/day</p>
                </div>
                <button
                  className="rent-btn"
                  onClick={(e) => {
                    e.stopPropagation();
                    onRent(vehicle);
                  }}
                >
                  Rent Now
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export default VehicleList;
